SELECT "U_DocType" AS "DocType", CASE WHEN COALESCE("U_DocEntry",'') <> '' THEN "U_DocNum" ELSE '' END AS "DocNum", CASE WHEN COALESCE("U_DocEntry",'') = '' THEN "U_DraftNum" ELSE '' END AS "DraftNum", COALESCE(NULLIF("U_CreatorName",''),"U_User") AS "Creator", COALESCE(NULLIF("U_TemplateName",''),"U_TemplateKey") AS "TemplateName", CASE "U_Status" WHEN 'W' THEN '보류' WHEN 'Y' THEN '승인' WHEN 'N' THEN '거부' WHEN 'P' THEN '생성' WHEN 'A' THEN '승인 및 생성' WHEN 'C' THEN '취소됨' ELSE "U_Status" END AS "Status", "U_Remarks" AS "Remarks", "U_Draft" AS "DraftKey", "U_DraftUser" AS "DraftUser", "U_DraftDate" AS "DraftDate", "U_DraftTime" AS "DraftTime", "U_DraftNote" AS "DraftNote", "U_DocEntry" AS "DocEntry", "U_ObjType" AS "ObjType", "U_TemplateKey" AS "TemplateKey", "U_Hash" AS "Hash", "U_WddCode" AS "ApprovalKey", COALESCE(F."DocTotal", D."DocTotal", C."U_Amount") AS "Amount", (SELECT "MainCurncy" FROM "OADM") AS "Currency", CASE WHEN F."DocTotal" IS NOT NULL OR D."DocTotal" IS NOT NULL THEN 'Y' ELSE C."U_AmtKnown" END AS "AmountKnown" FROM "@PVI_ARVC" C LEFT JOIN "ODRF" D ON TO_NVARCHAR(D."DocEntry")=C."U_Draft" AND D."ObjType"=C."U_ObjType" LEFT JOIN (SELECT '23' AS "Type", "DocEntry", "DocTotal" FROM "OQUT" UNION ALL SELECT '17' AS "Type", "DocEntry", "DocTotal" FROM "ORDR" UNION ALL SELECT '15' AS "Type", "DocEntry", "DocTotal" FROM "ODLN" UNION ALL SELECT '16' AS "Type", "DocEntry", "DocTotal" FROM "ORDN" UNION ALL SELECT '13' AS "Type", "DocEntry", "DocTotal" FROM "OINV" UNION ALL SELECT '14' AS "Type", "DocEntry", "DocTotal" FROM "ORIN" UNION ALL SELECT '203' AS "Type", "DocEntry", "DocTotal" FROM "ODPI" UNION ALL SELECT '1470000113' AS "Type", "DocEntry", "DocTotal" FROM "OPRQ" UNION ALL SELECT '540000006' AS "Type", "DocEntry", "DocTotal" FROM "OPQT" UNION ALL SELECT '22' AS "Type", "DocEntry", "DocTotal" FROM "OPOR" UNION ALL SELECT '20' AS "Type", "DocEntry", "DocTotal" FROM "OPDN" UNION ALL SELECT '21' AS "Type", "DocEntry", "DocTotal" FROM "ORPD" UNION ALL SELECT '18' AS "Type", "DocEntry", "DocTotal" FROM "OPCH" UNION ALL SELECT '19' AS "Type", "DocEntry", "DocTotal" FROM "ORPC" UNION ALL SELECT '204' AS "Type", "DocEntry", "DocTotal" FROM "ODPO" UNION ALL SELECT '67' AS "Type", "DocEntry", "DocTotal" FROM "OWTR" UNION ALL SELECT '1250000001' AS "Type", "DocEntry", "DocTotal" FROM "OWTQ" UNION ALL SELECT '59' AS "Type", "DocEntry", "DocTotal" FROM "OIGN" UNION ALL SELECT '60' AS "Type", "DocEntry", "DocTotal" FROM "OIGE" UNION ALL SELECT '234000031' AS "Type", "DocEntry", "DocTotal" FROM "ORRR" UNION ALL SELECT '234000032' AS "Type", "DocEntry", "DocTotal" FROM "OPRR") F ON TO_NVARCHAR(F."DocEntry")=C."U_DocEntry" AND F."Type"=C."U_ObjType"